const input = $input.first()?.json || {};

function asTrimmedString(value) {
  if (value === undefined || value === null) return '';
  return String(value).trim();
}

function readNumber(value, defaultValue, fieldName) {
  if (value === undefined || value === null || value === '') return defaultValue;
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) {
    throw new Error(`${fieldName} 必须是数字`);
  }
  return parsed;
}

function isImageUrl(value) {
  return /^https?:\/\//i.test(value) || /^data:image\//i.test(value);
}

function normalizeLocalPath(value) {
  let path = value.trim();
  if (/^file:\/\//i.test(path)) {
    path = path.replace(/^file:\/\//i, '');
    if (/^\/[A-Za-z]:\//.test(path)) {
      path = path.slice(1);
    }
  }
  return path.replace(/\\/g, '/');
}

const userPrompt = asTrimmedString(input.userPrompt);
if (!userPrompt) {
  throw new Error('userPrompt 为必选参数，不能为空');
}

const sysPrompt = asTrimmedString(input.sysPrompt);
const temperature = readNumber(input.temperature, 0.7, 'temperature');
const topP = readNumber(input.top_p, 0.8, 'top_p');

const imageFields = ['imageAdd1', 'imageAdd2', 'imageAdd3'];
const imageSlots = [];
const urlImages = [];
const localImages = [];

for (let index = 0; index < imageFields.length; index++) {
  const key = imageFields[index];
  const source = asTrimmedString(input[key]);
  if (!source) continue;

  if (isImageUrl(source)) {
    const image = {
      index,
      key,
      type: 'url',
      source,
      url: source,
    };
    imageSlots.push(image);
    urlImages.push(image);
  } else {
    const path = normalizeLocalPath(source);
    const image = {
      index,
      key,
      type: 'local',
      source,
      path,
    };
    imageSlots.push(image);
    localImages.push(image);
  }
}

const context = {
  constants: input.constants || {},
  userPrompt,
  sysPrompt,
  temperature,
  top_p: topP,
  imageSlots,
  urlImages,
  localImages,
  imageCount: imageSlots.length,
  hasLocalImages: localImages.length > 0,
};

if (localImages.length > 0) {
  context.firstLocalPath = localImages[0].path;
}

return [{ json: context }];

const context = $input.first()?.json;
if (!context) {
  throw new Error('缺少标准化输入上下文');
}

const localImages = Array.isArray(context.localImages) ? context.localImages : [];
if (localImages.length === 0) {
  return [];
}

return localImages.map((localImage) => ({
  json: {
    context,
    localImage,
  },
}));

const readItems = $input.all();
const explodedItems = $('Explode Local Images').all();

if (readItems.length !== explodedItems.length) {
  throw new Error(`本地图片读取数量不匹配：期望 ${explodedItems.length}，实际 ${readItems.length}`);
}

function inferMimeType(fileNameOrPath) {
  const lower = String(fileNameOrPath || '').toLowerCase();
  if (lower.endsWith('.jpg') || lower.endsWith('.jpeg')) return 'image/jpeg';
  if (lower.endsWith('.png')) return 'image/png';
  if (lower.endsWith('.webp')) return 'image/webp';
  if (lower.endsWith('.gif')) return 'image/gif';
  if (lower.endsWith('.bmp')) return 'image/bmp';
  return 'image/png';
}

const localDataUrls = [];
let context = null;

for (let i = 0; i < readItems.length; i++) {
  const exploded = explodedItems[i].json;
  context = context || exploded.context;
  const localImage = exploded.localImage;
  const binary = readItems[i].binary?.data;

  if (!binary) {
    throw new Error(`未读取到本地图片二进制数据：${localImage.source}`);
  }

  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const fileName = binary.fileName || localImage.path;
  const mimeType = binary.mimeType || inferMimeType(fileName);

  if (!String(mimeType).startsWith('image/')) {
    throw new Error(`本地文件不是图片 MIME 类型：${localImage.source} (${mimeType})`);
  }

  localDataUrls.push({
    index: localImage.index,
    key: localImage.key,
    type: 'local',
    source: localImage.source,
    path: localImage.path,
    mimeType,
    fileName,
    url: `data:${mimeType};base64,${buffer.toString('base64')}`,
  });
}

localDataUrls.sort((a, b) => a.index - b.index);

return [{
  json: {
    context,
    localDataUrls,
  },
}];

const input = $input.first()?.json || {};
const context = input.context || input;
const localDataUrls = Array.isArray(input.localDataUrls) ? input.localDataUrls : [];
const shared = context.constants || {};
const modelRun = String(shared.model?.Model_Run || '').trim();
const baseUrlRun = String(shared.BaseUrl?.BaseUrl_Run || '').trim();
const apiKeyRun = String(shared.Authorization?.APIKey_Run || '').trim();

if (!modelRun) {
  throw new Error('缺少 constants.model.Model_Run，无法构造模型请求');
}

if (!baseUrlRun) {
  throw new Error('缺少 constants.BaseUrl.BaseUrl_Run，无法构造模型请求');
}

if (!apiKeyRun) {
  throw new Error('缺少 constants.Authorization.APIKey_Run，无法构造模型请求');
}

if (!context.userPrompt) {
  throw new Error('缺少 userPrompt，无法构造 Qwen 请求');
}

const localByIndex = new Map(localDataUrls.map((image) => [image.index, image]));
const imageContents = [];
const imageSources = [];

for (const slot of context.imageSlots || []) {
  if (slot.type === 'url') {
    imageContents.push({
      type: 'image_url',
      image_url: {
        url: slot.url,
      },
    });
    imageSources.push({
      index: slot.index,
      key: slot.key,
      type: 'url',
      source: slot.source,
    });
    continue;
  }

  const converted = localByIndex.get(slot.index);
  if (!converted) {
    throw new Error(`本地图片未成功转换为 data URL：${slot.source}`);
  }

  imageContents.push({
    type: 'image_url',
    image_url: {
      url: converted.url,
    },
  });
  imageSources.push({
    index: slot.index,
    key: slot.key,
    type: 'local',
    source: slot.source,
    path: converted.path,
    mimeType: converted.mimeType,
    fileName: converted.fileName,
  });
}

const expectedImageCount = Number(context.imageCount || 0);
if (imageContents.length !== expectedImageCount) {
  throw new Error(`图片数量不一致：期望 ${expectedImageCount}，实际 ${imageContents.length}`);
}

const outputInstruction = '你必须只输出一个合法 JSON 对象，不要输出 Markdown，不要输出代码块。JSON 必须包含字符串字段 messageContent，格式示例：{"messageContent":"你的回答文本"}。';
const systemContent = context.sysPrompt
  ? `${context.sysPrompt}\n\n${outputInstruction}`
  : outputInstruction;

const messages = [
  {
    role: 'system',
    content: systemContent,
  },
];

if (imageContents.length > 0) {
  messages.push({
    role: 'user',
    content: [
      {
        type: 'text',
        text: context.userPrompt,
      },
      ...imageContents,
    ],
  });
} else {
  messages.push({
    role: 'user',
    content: context.userPrompt,
  });
}

const request = {
  model: modelRun,
  messages,
  enable_thinking: false,
  response_format: {
    type: 'json_object',
  },
  temperature: context.temperature ?? 0.7,
  top_p: context.top_p ?? 0.8,
  stream: false,
};

const { constants: sourceConstants = {}, ...sourceContext } = context;
const source = {
  ...sourceContext,
  imageSources,
  requestMeta: {
    model: request.model,
    imageCount: imageContents.length,
    imageSources,
    temperature: request.temperature,
    top_p: request.top_p,
  },
};

return [{
  json: {
    request,
    constants: sourceConstants,
    source,
  },
}];

const response = $input.first()?.json || {};
const meta = $('Build Qwen Request').first()?.json?.source?.requestMeta || {};
const choice = Array.isArray(response.choices) ? response.choices[0] : undefined;

if (!choice) {
  throw new Error('阿里百炼响应中缺少 choices[0]');
}

const content = choice.message?.content;
if (typeof content !== 'string' || !content.trim()) {
  throw new Error('Qwen3.7-plus 未返回可解析的文本内容');
}

let parsed;
try {
  parsed = JSON.parse(content.trim());
} catch (error) {
  throw new Error(`Qwen3.7-plus 返回内容不是合法 JSON：${content}`);
}

let messageContent;
if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
  if (typeof parsed.messageContent === 'string') {
    messageContent = parsed.messageContent;
  } else {
    messageContent = JSON.stringify(parsed);
  }
} else {
  throw new Error('Qwen3.7-plus 返回 JSON 不是对象');
}

return [{
  json: {
    messageContent,
    model: response.model || meta.model || 'qwen3.7-plus',
    usage: response.usage || null,
    finishReason: choice.finish_reason || choice.finishReason || null,
    imageCount: meta.imageCount || 0,
  },
}];
